1	// The grown-ups' changes to the game's rows: what a change may say, and how the saved changes become applyRows' `over`.
2	//
3	// checkChange is the one rule book. The cloud functions "Grown-ups/Save Change" and "Grown-ups/Remove Change" carry a
4	// copy of the text between the two CHECKCHANGE markers (script files do not run in cloud functions yet), and
5	// tests/rows-guard.test.mjs fails if the two copies ever differ. The server refuses whatever it says no to; the game
6	// asks it again before applying a saved change, so a row that reached the database some other way is still skipped.
7	
8	// ---- CHECKCHANGE BEGIN ----
9	function checkChange(table, rowId, fields) {
10	  const BUILT_IN = {
11	    moves: ['plie', 'releve', 'bras', 'chasseD', 'chasseG', 'avance', 'recule', 'tourne', 'saute', 'reception', 'clap', 'vague', 'descente', 'remonte', 'pirouette', 'arabesque', 'sautChat', 'kick', 'roulade', 'moonwalk', 'toprock', 'grandJete', 'fouette', 'freeze', 'echange', 'reverence'],
12	    outfits: ['justaucorps', 'jupette', 'tutu', 'robe', 'marin', 'fee', 'papillon', 'cygne', 'lapin', 'flocon', 'etoile', 'flamenco', 'princesse', 'street', 'abeille', 'disco'],
13	    hairs: ['chignon', 'queue', 'tresses', 'carre', 'couettes', 'laches', 'macarons', 'couronne', 'ruban', 'afro'],
14	    shoes: ['demi', 'pieds', 'pointes', 'jazz', 'baskets', 'paillettes', 'claquettes'],
15	    accs: ['aucun', 'noeud', 'tiare', 'fleurs', 'ailes', 'oreilles', 'casquette', 'beret', 'baguette', 'antennes'],
16	    start: ['start'],
17	  };
18	  // only what the shop already sells has a price to change: a starter costume stays free, so no child's plan locks up
19	  const PRICED = {
20	    outfits: ['robe', 'marin', 'fee', 'papillon', 'cygne', 'lapin', 'flocon', 'etoile', 'flamenco', 'princesse', 'abeille', 'disco'],
21	    hairs: ['couettes', 'laches', 'macarons', 'couronne', 'ruban', 'afro'],
22	    shoes: ['pointes', 'jazz', 'baskets', 'paillettes', 'claquettes'],
23	    accs: ['tiare', 'fleurs', 'ailes', 'oreilles', 'casquette', 'beret', 'baguette', 'antennes'],
24	  };
25	  const NAME = { name: true }, PRICE = { min: 0, max: 200 }, MINUTES = { min: 1, max: 15 };
26	  // what may change on a row the game ships with
27	  const CHANGE = {
28	    start: { stars: { min: 0, max: 300 } },
29	    moves: { fr: NAME, en: NAME, d: { min: 1, max: 3 } },
30	    outfits: { fr: NAME, en: NAME, price: PRICE, min: MINUTES },
31	    hairs: { fr: NAME, en: NAME, price: PRICE, min: MINUTES },
32	    shoes: { fr: NAME, en: NAME, price: PRICE },
33	    accs: { fr: NAME, en: NAME, price: PRICE },
34	  };
35	  const ICONS = ['✨', '🌟', '⭐', '💫', '🌈', '🌸', '🌺', '🌼', '🍀', '🦋', '🐞', '🐝', '🐬', '🦄', '🐱', '🐶', '🐰', '🦊', '🐻', '🐼', '🐸', '🐧', '🦩', '🦚', '🎀', '🎈', '🎵', '🥁', '🎺', '🎻', '💃', '🕺', '🩰', '👑', '💎', '❄️', '☀️', '🌙', '🌊', '🍓', '🧁', '👗', '🩱', '🧚', '🚀', '⚡', '🌀'];
36	  const STYLES = ['classique', 'contemporain', 'jazz', 'hiphop'];
37	  const THEMES = ['lucioles', 'lapins', 'vent', 'marins', 'lumiere', 'lac', 'street', 'battle', 'disco'];
38	  // a new step dances like a step the game has (its `like`); swapping places is the one step that can't be copied
39	  const LIKE_MOVES = BUILT_IN.moves.filter((id) => id !== 'echange');
40	  // a new row: every field its table's rows have, nothing else (applyRows takes a new row whole)
41	  const ADD = {
42	    moves: {
43	      fr: NAME, en: NAME, c: { oneOf: [4, 8] }, d: { min: 1, max: 3 }, a: { min: 0, max: 2 }, b: { min: 0, max: 2 },
44	      dx: { min: -1, max: 1 }, dz: { min: -1, max: 1 }, st: { styles: true }, icon: { oneOf: ICONS }, like: { oneOf: LIKE_MOVES },
45	    },
46	    outfits: {
47	      fr: NAME, en: NAME, min: MINUTES, price: PRICE, icon: { oneOf: ICONS }, themes: { themes: true }, like: { oneOf: BUILT_IN.outfits },
48	    },
