52	  const ADDED_ID = /^x(0[1-9]|1[0-9]|20)$/;
53	
54	  const refuse = (message) => ({ ok: false, message });
55	  const isPlainObject = (o) => o !== null && typeof o === 'object' && !Array.isArray(o) && Object.getPrototypeOf(o) === Object.prototype;
56	
