58	  const LEET = { 0: 'o', 1: 'i', 3: 'e', 4: 'a', 5: 's', 7: 't', '@': 'a', $: 's', '!': 'i' };
59	  const plain = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().split('').map((ch) => LEET[ch] || ch).join('');
60	  const squeeze = (s) => s.replace(/(.)\1+/g, '$1');
61	  const RUDE_WORDS = [
